export const getMappings = (
		data: string,
		): number[][] => {

	const lMappings: number[][] = []
	var sum: number[] = [0, 0, 0, 0]
	let i1 = 0;for (const line of data.split(";")) {const lineNum = i1++;
		sum[0] = 0
		decodeLine(line).forEach((p) => {
			for (let end1 = p.length, i2 = 0; i2 < end1; ++i2) {const i = i2;
				sum[i] += p[i]
			}
			return lMappings.push([lineNum, sum[0], sum[1], sum[2], sum[3]])
		})
	}
	return lMappings
}

